package com.ragestars.overlay;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.PixelFormat;import android.os.*;import android.view.*;import android.widget.*;
public class FloatingMenuService extends Service {
 private WindowManager wm;private View bubble,panel;private WindowManager.LayoutParams bl,pl;private int tab=0;private boolean opened=false;
 public void onCreate(){super.onCreate();startForeground(41,notification());wm=(WindowManager)getSystemService(WINDOW_SERVICE);createBubble();}
 private Notification notification(){String ch="rs_overlay";if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(ch,"RageStars overlay",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}return new Notification.Builder(this,ch).setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("RageStars работает").setContentText("Плавающая кнопка меню активна").build();}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 private WindowManager.LayoutParams lp(int w,int h){int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;return new WindowManager.LayoutParams(w,h,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);}
 private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);return t;}
 private android.graphics.drawable.GradientDrawable bg(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),0xFF6D2739);return d;}
 private void createBubble(){TextView b=label("RS",18,Color.WHITE);b.setTypeface(null,1);b.setBackground(bg(0xFFE3264F,100));bubble=b;bl=lp(dp(58),dp(58));bl.gravity=Gravity.TOP|Gravity.START;bl.x=20;bl.y=240;b.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=bl.x;oy=bl.y;return true;}if(e.getAction()==2){bl.x=ox+(int)(e.getRawX()-sx);bl.y=oy+(int)(e.getRawY()-sy);wm.updateViewLayout(bubble,bl);return true;}if(e.getAction()==1){if(Math.abs(e.getRawX()-sx)<12&&Math.abs(e.getRawY()-sy)<12){if(opened)closePanel();else openPanel();}return true;}return true;}});wm.addView(bubble,bl);}
 private void openPanel(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(10),dp(12),dp(12));box.setBackground(bg(0xF0181016,18));panel=box;TextView title=label("RAGESTARS • MENU",18,0xFFFF5571);title.setTypeface(null,1);box.addView(title,new LinearLayout.LayoutParams(-1,dp(44)));LinearLayout tabs=new LinearLayout(this);String[] names={"ОБЩЕЕ","ИНТЕРФЕЙС","ЛИЦЕНЗИЯ"};for(int i=0;i<3;i++){final int n=i;Button bt=new Button(this);bt.setText(names[i]);bt.setTextSize(10);bt.setTextColor(-1);bt.setBackgroundTintList(android.content.res.ColorStateList.valueOf(i==tab?0xFFB51F42:0xFF35232C));tabs.addView(bt,new LinearLayout.LayoutParams(0,dp(46),1));bt.setOnClickListener(v->{tab=n;refresh();});}box.addView(tabs);FrameLayout area=new FrameLayout(this);box.addView(area,new LinearLayout.LayoutParams(-1,dp(180)));TextView close=label("ЗАКРЫТЬ ×",14,0xFFFF8093);close.setBackground(bg(0xFF5A1D30,10));box.addView(close,new LinearLayout.LayoutParams(-1,dp(42)));close.setOnClickListener(v->closePanel());pl=lp(dp(310),dp(300));pl.gravity=Gravity.TOP|Gravity.START;pl.x=dp(78);pl.y=dp(170);wm.addView(panel,pl);opened=true;refresh();}
 private void refresh(){if(!(panel instanceof LinearLayout))return;FrameLayout area=(FrameLayout)((LinearLayout)panel).getChildAt(2);area.removeAllViews();LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(8),dp(12),dp(8),dp(4));if(tab==0){c.addView(label("Добро пожаловать в RageStars",16,-1));c.addView(label("Удерживайте RS, чтобы переместить кнопку.",12,0xFFBDAEB4));}else if(tab==1){c.addView(label("Тема: тёмная / красная",15,-1));c.addView(label("Размер панели: стандартный",13,0xFFBDAEB4));}else{c.addView(label("Лицензия проверяется сервером",15,-1));c.addView(label("Привязка к этой установке",12,0xFFBDAEB4));}area.addView(c);}
 private void closePanel(){if(panel!=null){wm.removeView(panel);panel=null;}opened=false;}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public void onDestroy(){if(panel!=null)wm.removeView(panel);if(bubble!=null)wm.removeView(bubble);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
